insert into public.teams(id,owner_id,title,subtitle,category,description,skills,capacity,starts_on,ends_on,contact_email,work_mode,commitment) values ('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','CU NextGen Hackathon','เปลี่ยนไอเดียให้เป็นนวัตกรรม ไปด้วยกัน','Hackathon','กำลังรวมทีมลงแข่งขัน Hackathon เพื่อออกแบบแพลตฟอร์มแก้ปัญหาชีวิตในมหาวิทยาลัย เรามีคนทำ Business และ Frontend แล้ว อยากได้เพื่อนที่สนใจ UX/UI และ Backend มาร่วมสร้างต้นแบบและนำเสนอไอเดียด้วยกัน ไม่ต้องเคยแข่งมาก่อน แค่พร้อมเรียนรู้ก็พอ!',ARRAY['UI/UX','Backend','React']::text[],5,'2026-11-01','2026-12-15','cunextgen@example.com','Hybrid · จุฬาฯ / Online','4–6 ชั่วโมง / สัปดาห์') on conflict(id) do nothing;
